];

// ── Helper: point on circle boundary ──
function circleEdge(x1, y1, x2, y2, r) {
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx*dx + dy*dy);
  if (len === 0) return [x2, y2];
  return [x2 - r * dx / len, y2 - r * dy / len];
}
function circleEdgeStart(x1, y1, x2, y2, r) {
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx*dx + dy*dy);
  if (len === 0) return [x1, y1];
  return [x1 + r * dx / len, y1 + r * dy / len];
}

