function isMatched(matching, li, ri) {
  for (var i = 0; i < matching.length; i++) {
    if (matching[i][0] === li && matching[i][1] === ri) return true;
  }
  return false;
}

function drawPanelAB(g, pos, edgeList, matching, directed) {
  // Draw edges
  for (var i = 0; i < edgeList.length; i++) {
