// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
var W = 1200, H = 470;
draw.viewbox(0, 0, W, H);

// ── Graph data (FIXED: matching2 = L2-R1, L3-R3 so augmenting path yields matching3) ──
var edges = [[0,0],[1,0],[1,2],[2,1],[2,2],[3,2],[4,2],[4,3]];
var matching2 = [[1,0],[2,2]];  // L2-R1, L3-R3
var matching3 = [[1,0],[2,1],[4,2]];  // L2-R1, L3-R2, L5-R3
var flowPaths = [[1,0],[2,1],[4,2]];
// Augmenting path: L5→R3 (unmatched), R3→L3 (matched backward), L3→R2 (unmatched)
// Flip: remove L3-R3, add L5-R3 and L3-R2 → {L2-R1, L5-R3, L3-R2} = matching3 ✓
var augmentingPath = { edges: [[4,2],[2,2],[2,1]], nodes: {L:[4,2], R:[2,1]} };

// ── Positions (node radius increased to 26) ──
var nr = 26;
var P = {
  a: { Lx: 65, Rx: 225, Ly: [52,132,212,292,372], Ry: [82,172,262,352] },
  b: { Lx: 405, Rx: 565, Ly: [52,132,212,292,372], Ry: [82,172,262,352] },
  c: { sx: 700, Lx: 830, Rx: 980, tx: 1110, Ly: [52,132,212,292,372], Ry: [82,172,262,352] }
};

// ── State ──
var currentPanel = 'all';
var augmentState = 'done';
var currentStep = 0;
var highlightedPath = -1;
var showingAugmentingPath = false;
var showingFlipped = false;

// ── Steps data (5 steps: overview + 4 from blueprint) ──
var steps = [
  { title: "Overview", narration: "All three panels shown together. Panel (a) has a matching of size 2, panel (b) shows the maximum matching of size 3 after augmentation, and panel (c) reveals the equivalent flow network with 3 vertex-disjoint s-to-t paths.", panel: 'all', augment: 'done' },
  { title: "A matching of size 2", narration: "Panel (a) shows a bipartite graph with 5 left nodes and 4 right nodes. Two edges are thickened (gray band) forming a valid matching: no two share an endpoint. This is not maximum — more nodes can still be covered.", panel: 'a', augment: 'idle' },
  { title: "Augment to size 3", narration: "An augmenting path L5→R3→L3→R2 alternates between unmatched and matched edges. Flipping it removes L3-R3 and adds L5-R3 and L3-R2, growing the matching from 2 to 3 — the maximum for this graph.", panel: 'b', augment: 'done' },
  { title: "The flow network view", narration: "Panel (c) adds a source s and sink t with unit-capacity directed edges. The three matched edges from (b) now appear as three vertex-disjoint s-to-t paths (thick gray). A max flow of value 3 equals a matching of size 3.", panel: 'c', augment: 'done' },
  { title: "One path = one matched pair", narration: "Click any highlighted s-to-t path in panel (c): it traces s → one L node → one R node → t, and the middle L-R edge is exactly one of the three matched edges from panel (b). Each unit of flow is one matched pair.", panel: 'c', augment: 'done' }
];

// ── Helpers ──
function circleEdge(x1, y1, x2, y2, r) {
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx*dx + dy*dy);
  if (len === 0) return [x2, y2];
  return [x2 - r * dx / len, y2 - r * dy / len];
}
function circleEdgeStart(x1, y1, x2, y2, r) {
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx*dx + dy*dy);
  if (len === 0) return [x1, y1];
  return [x1 + r * dx / len, y1 + r * dy / len];
}
function isMatched(matching, li, ri) {
  for (var i = 0; i < matching.length; i++) {
    if (matching[i][0] === li && matching[i][1] === ri) return true;
  }
  return false;
}
function isOnAugPath(augPath, li, ri) {
  for (var i = 0; i < augPath.edges.length; i++) {
    if (augPath.edges[i][0] === li && augPath.edges[i][1] === ri) return true;
  }
  return false;
}

// ── Main render ──
function render() {
  draw.clear();
  var d2 = draw.defs();
  var m2 = d2.marker(10, 7, function(add) {
    add.path('M0,0 L10,3.5 L0,7 Z').fill('#000');
  });
  m2.attr({ refX: 9, refY: 3.5, orient: 'auto', markerWidth: 9, markerHeight: 7 });

  var showA = (currentPanel === 'all' || currentPanel === 'a');
  var showB = (currentPanel === 'all' || currentPanel === 'b');
  var showC = (currentPanel === 'all' || currentPanel === 'c');
  var dimA = showA ? 1 : 0.25;
  var dimB = showB ? 1 : 0.25;
  var dimC = showC ? 1 : 0.25;

  var matchA = matching2;
  var matchB = (augmentState === 'done') ? matching3 : matching2;

  // ── Panel (a) ──
  var gA = draw.group().opacity(dimA);
  drawPanelAB(gA, P.a, edges, matchA, false, null);
  gA.text('L').attr({ x: P.a.Lx, y: 415, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 16 });
  gA.text('R').attr({ x: P.a.Rx, y: 415, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 16 });
  gA.text('(a)').attr({ x: (P.a.Lx + P.a.Rx) / 2, y: 450, 'text-anchor': 'middle', 'font-family': 'serif', 'font-size': 15 });

  // ── Panel (b) ──
  var gB = draw.group().opacity(dimB);
  var augToShow = (showingAugmentingPath && currentPanel !== 'c') ? augmentingPath : null;
  drawPanelAB(gB, P.b, edges, matchB, false, augToShow);
  gB.text('L').attr({ x: P.b.Lx, y: 415, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 16 });
  gB.text('R').attr({ x: P.b.Rx, y: 415, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 16 });
  gB.text('(b)').attr({ x: (P.b.Lx + P.b.Rx) / 2, y: 450, 'text-anchor': 'middle', 'font-family': 'serif', 'font-size': 15 });

  // ── Panel (c) ──
  var gC = draw.group().opacity(dimC);
  if (highlightedPath >= 0) {
    drawPanelCHighlight(gC, m2, highlightedPath);
  } else {
    drawPanelC(gC, m2, showingAugmentingPath ? augmentingPath : null);
  }
  gC.text('L').attr({ x: P.c.Lx, y: 415, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 16 });
  gC.text('R').attr({ x: P.c.Rx, y: 415, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 16 });
  gC.text('(c)').attr({ x: (P.c.Lx + P.c.Rx) / 2, y: 450, 'text-anchor': 'middle', 'font-family': 'serif', 'font-size': 15 });
}

function drawPanelAB(g, pos, edgeList, matching, directed, augPath) {
  // Draw augmenting path highlight first (behind everything)
  if (augPath) {
    for (var i = 0; i < augPath.edges.length; i++) {
      var li = augPath.edges[i][0], ri = augPath.edges[i][1];
      g.line(pos.Lx, pos.Ly[li], pos.Rx, pos.Ry[ri]).stroke({ color: '#e74c3c', width: 16, linecap: 'round' }).opacity(0.3);
    }
  }
  // Draw edges
  for (var i = 0; i < edgeList.length; i++) {
    var li = edgeList[i][0], ri = edgeList[i][1];
    var x1 = pos.Lx, y1 = pos.Ly[li];
    var x2 = pos.Rx, y2 = pos.Ry[ri];
    var matched = isMatched(matching, li, ri);
    var onAugPath = augPath && isOnAugPath(augPath, li, ri);

    if (matched && !onAugPath) {
      g.line(x1, y1, x2, y2).stroke({ color: '#999', width: 12, linecap: 'round' }).opacity(0.6);
    }
    if (onAugPath) {
      g.line(x1, y1, x2, y2).stroke({ color: '#e74c3c', width: 5, linecap: 'round' }).opacity(0.9);
    }
    g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 1.2 });
  }
  // Draw nodes
  for (var i = 0; i < 5; i++) {
    var isAugNode = augPath && augPath.nodes.L.indexOf(i) >= 0;
    g.circle(nr * 2).attr({ cx: pos.Lx, cy: pos.Ly[i], fill: isAugNode ? '#fdebd0' : '#ddd', stroke: isAugNode ? '#e74c3c' : '#000', 'stroke-width': isAugNode ? 2.5 : 1.2 });
  }
  for (var i = 0; i < 4; i++) {
    var isAugNode = augPath && augPath.nodes.R.indexOf(i) >= 0;
    g.circle(nr * 2).attr({ cx: pos.Rx, cy: pos.Ry[i], fill: isAugNode ? '#fdebd0' : '#ddd', stroke: isAugNode ? '#e74c3c' : '#000', 'stroke-width': isAugNode ? 2.5 : 1.2 });
  }
}

function drawPanelC(g, markerRef, augPath) {
  var pos = P.c;
  var matchToShow = (augmentState === 'done') ? matching3 : matching2;

  // s→L edges
  for (var i = 0; i < 5; i++) {
    var sx = pos.sx, sy = 212;
    var lx = pos.Lx, ly = pos.Ly[i];
    var start = circleEdgeStart(sx, sy, lx, ly, nr);
    var end = circleEdge(sx, sy, lx, ly, nr + 2);
    var onPath = false;
    for (var p = 0; p < flowPaths.length; p++) {
      if (flowPaths[p][0] === i && augmentState === 'done') onPath = true;
    }
    var onAug = augPath && augPath.nodes.L.indexOf(i) >= 0;
    if (onPath && !onAug) {
      g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#999', width: 12, linecap: 'round' }).opacity(0.6);
    }
    if (onAug) {
      g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#e74c3c', width: 5, linecap: 'round' }).opacity(0.9);
    }
    g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#000', width: 1.2 }).attr({ 'marker-end': 'url(#' + markerRef.id() + ')' });
  }

  // L→R edges
  for (var i = 0; i < edges.length; i++) {
    var li = edges[i][0], ri = edges[i][1];
    var x1 = pos.Lx, y1 = pos.Ly[li];
    var x2 = pos.Rx, y2 = pos.Ry[ri];
    var start = circleEdgeStart(x1, y1, x2, y2, nr);
    var end = circleEdge(x1, y1, x2, y2, nr + 2);
    var matched = isMatched(matchToShow, li, ri);
    var onAug = augPath && isOnAugPath(augPath, li, ri);

    if (matched && augmentState === 'done' && !onAug) {
      g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#999', width: 12, linecap: 'round' }).opacity(0.6);
    }
    if (onAug) {
      g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#e74c3c', width: 5, linecap: 'round' }).opacity(0.9);
    }
    g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#000', width: 1.2 }).attr({ 'marker-end': 'url(#' + markerRef.id() + ')' });
  }

  // R→t edges
  for (var i = 0; i < 4; i++) {
    var rx = pos.Rx, ry = pos.Ry[i];
    var tx = pos.tx, ty = 212;
    var start = circleEdgeStart(rx, ry, tx, ty, nr);
    var end = circleEdge(rx, ry, tx, ty, nr + 2);
    var onPath = false;
    for (var p = 0; p < flowPaths.length; p++) {
      if (flowPaths[p][1] === i && augmentState === 'done') onPath = true;
    }
    var onAug = augPath && augPath.nodes.R.indexOf(i) >= 0;
    if (onPath && !onAug) {
      g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#999', width: 12, linecap: 'round' }).opacity(0.6);
    }
    if (onAug) {
      g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#e74c3c', width: 5, linecap: 'round' }).opacity(0.9);
    }
    g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#000', width: 1.2 }).attr({ 'marker-end': 'url(#' + markerRef.id() + ')' });
  }

  // Nodes
  g.circle(nr * 2).attr({ cx: pos.sx, cy: 212, fill: '#ddd', stroke: '#000', 'stroke-width': 1.2 });
  g.text('s').attr({ x: pos.sx, y: 217, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 15 });
  for (var i = 0; i < 5; i++) {
    var isAug = augPath && augPath.nodes.L.indexOf(i) >= 0;
    g.circle(nr * 2).attr({ cx: pos.Lx, cy: pos.Ly[i], fill: isAug ? '#fdebd0' : '#ddd', stroke: isAug ? '#e74c3c' : '#000', 'stroke-width': isAug ? 2.5 : 1.2 });
  }
  for (var i = 0; i < 4; i++) {
    var isAug = augPath && augPath.nodes.R.indexOf(i) >= 0;
    g.circle(nr * 2).attr({ cx: pos.Rx, cy: pos.Ry[i], fill: isAug ? '#fdebd0' : '#ddd', stroke: isAug ? '#e74c3c' : '#000', 'stroke-width': isAug ? 2.5 : 1.2 });
  }
  g.circle(nr * 2).attr({ cx: pos.tx, cy: 212, fill: '#ddd', stroke: '#000', 'stroke-width': 1.2 });
  g.text('t').attr({ x: pos.tx, y: 217, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 15 });

  // Clickable path overlays
