      (function(pathIdx) {
        var li = flowPaths[pathIdx][0], ri = flowPaths[pathIdx][1];
        var sx = pos.sx, sy = 212;
        var lx = pos.Lx, ly = pos.Ly[li];
        var rx = pos.Rx, ry = pos.Ry[ri];
        var tx = pos.tx, ty = 212;
        var clickPath = g.path('M' + sx + ',' + sy + ' L' + lx + ',' + ly + ' L' + rx + ',' + ry + ' L' + tx + ',' + ty)
          .fill('none').stroke({ color: 'transparent', width: 20 }).css('cursor', 'pointer');
        clickPath.on('click', function() {
          highlightedPath = pathIdx;
          showPopup('Flow path ' + (pathIdx + 1),
            'This s-to-t path goes: s → L' + (li+1) + ' → R' + (ri+1) + ' → t. ' +
            'The middle edge L' + (li+1) + '-R' + (ri+1) + ' is exactly one matched edge from panel (b). ' +
            'One unit of flow = one matched pair.');
          render();
        });
        clickPath.on('mousemove', function(e) {
          showTooltip('Path ' + (pathIdx+1) + ': s → L' + (li+1) + ' → R' + (ri+1) + ' → t (click for details)', e);
        });
