function drawPanelCHighlight(g, markerRef, hlPath) {
  var pos = P.c;
  var matchToShow = matching3;

  // s→L edges
  for (var i = 0; i < 5; i++) {
    var sx = pos.sx, sy = 212;
    var lx = pos.Lx, ly = pos.Ly[i];
