    if (matched) {
      g.line(start[0], start[1], end[0], end[1]).stroke({ color: isHL ? '#e67e22' : '#999', width: isHL ? 14 : 12, linecap: 'round' }).opacity(isHL ? 0.85 : 0.6);
    }
    g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#000', width: 1.2 }).attr({ 'marker-end': 'url(#' + markerRef.id() + ')' });
  }

  // R→t edges
  for (var i = 0; i < 4; i++) {
    var rx = pos.Rx, ry = pos.Ry[i];
    var tx = pos.tx, ty = 212;
    var start = circleEdgeStart(rx, ry, tx, ty, nr);
    var end = circleEdge(rx, ry, tx, ty, nr + 2);
    var onPath = false;
    for (var p = 0; p < flowPaths.length; p++) {
      if (flowPaths[p][1] === i) onPath = true;
    }
    var isHL = (hlPath >= 0 && flowPaths[hlPath] && flowPaths[hlPath][1] === i);
    if (onPath) {
      g.line(start[0], start[1], end[0], end[1]).stroke({ color: isHL ? '#e67e22' : '#999', width: isHL ? 14 : 12, linecap: 'round' }).opacity(isHL ? 0.85 : 0.6);
    }
    g.line(start[0], start[1], end[0], end[1]).stroke({ color: '#000', width: 1.2 }).attr({ 'marker-end': 'url(#' + markerRef.id() + ')' });
  }

  // Nodes
  g.circle(nr * 2).attr({ cx: pos.sx, cy: 212, fill: '#ddd', stroke: '#000', 'stroke-width': 1.2 });
  g.text('s').attr({ x: pos.sx, y: 217, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 15 });
  for (var i = 0; i < 5; i++) {
    var isHL = (hlPath >= 0 && flowPaths[hlPath] && flowPaths[hlPath][0] === i);
    g.circle(nr * 2).attr({ cx: pos.Lx, cy: pos.Ly[i], fill: isHL ? '#fdebd0' : '#ddd', stroke: isHL ? '#e67e22' : '#000', 'stroke-width': isHL ? 2.5 : 1.2 });
  }
  for (var i = 0; i < 4; i++) {
    var isHL = (hlPath >= 0 && flowPaths[hlPath] && flowPaths[hlPath][1] === i);
    g.circle(nr * 2).attr({ cx: pos.Rx, cy: pos.Ry[i], fill: isHL ? '#fdebd0' : '#ddd', stroke: isHL ? '#e67e22' : '#000', 'stroke-width': isHL ? 2.5 : 1.2 });
  }
  g.circle(nr * 2).attr({ cx: pos.tx, cy: 212, fill: '#ddd', stroke: '#000', 'stroke-width': 1.2 });
  g.text('t').attr({ x: pos.tx, y: 217, 'text-anchor': 'middle', 'font-family': 'serif', 'font-style': 'italic', 'font-size': 15 });

  // Clickable overlays
  for (var p = 0; p < flowPaths.length; p++) {
    (function(pathIdx) {
      var li = flowPaths[pathIdx][0], ri = flowPaths[pathIdx][1];
      var sx = pos.sx, sy = 212;
      var lx = pos.Lx, ly = pos.Ly[li];
      var rx = pos.Rx, ry = pos.Ry[ri];
