      var clickPath = g.path('M' + sx + ',' + sy + ' L' + lx + ',' + ly + ' L' + rx + ',' + ry + ' L' + tx + ',' + ty)
        .fill('none').stroke({ color: 'transparent', width: 20 }).css('cursor', 'pointer');
      clickPath.on('click', function() {
