// ── UI handlers ──
function update_panelView(v) {
  currentPanel = v;
  highlightedPath = -1;
  render();
}

function trigger_augmentStep() {
  if (augmentState === 'done') {
    // Reset to idle first, then animate
    augmentState = 'idle';
    showingAugmentingPath = false;
    showingFlipped = false;
    document.getElementById('augmentBtn').textContent = 'Find augmenting path';
    render();
    return;
  }
  if (augmentState === 'idle' && !showingAugmentingPath) {
