      showingAugmentingPath = false;
      augmentState = 'done';
      document.getElementById('augmentBtn').textContent = 'Augmenting path found!';
      render();
    }, 1400);
  }
}

// ── Step player ──
function applyStep(idx) {
  currentStep = idx;
  var s = steps[idx];
  currentPanel = s.panel;
  augmentState = s.augment;
  highlightedPath = -1;
  showingAugmentingPath = false;
  showingFlipped = false;
