    document.getElementById('augmentBtn').textContent = 'Augmenting path found!';
  } else {
    document.getElementById('augmentBtn').textContent = 'Find augmenting path';
  }
  render();
}

function nextStep() {
  if (currentStep < steps.length - 1) applyStep(currentStep + 1);
}
function prevStep() {
  if (currentStep > 0) applyStep(currentStep - 1);
}

